<div class="content-wrapper"><section class="content-header"><h1>Basic Data Area</h1></section><section class="content"><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><div class="box box-primary"><div class="box-body"><p>Area menjadi batas akses untuk kapal, perusahaan, DO, SPP, KSOP, tagihan, dan piutang. Pengelolaan area hanya untuk administrator.</p><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><div class="row"><?php foreach(array('No_SPBB'=>'Kode Area / SPBB','Area'=>'Nama Area','Pic'=>'PIC') as $k=>$label): ?><div class="col-sm-4 form-group"><label><?= $label ?></label><input class="form-control" name="<?= $k ?>" maxlength="<?= $k==='No_SPBB'?30:100 ?>" <?= $k!=='Pic'?'required':'' ?>></div><?php endforeach; ?></div><button class="btn btn-primary">Tambah Area</button></form></div></div><div class="box"><div class="box-body"><table class="table table-striped"><tr><th>ID Area</th><th>Nama Area</th><th>PIC</th></tr><?php foreach($branches as $b): ?><tr><td><?= (int)$b['SpbbID'] ?></td><td><?= html_escape($b['SpbbName']) ?></td><td><?= html_escape(isset($b['Pic'])?$b['Pic']:'') ?></td></tr><?php endforeach; ?></table></div></div></section></div>